import { ToolCall, JsonValue } from '@vitest-evals/core';

type ToolCallLike = ToolCall;
type ScoreMetadata = {
    rationale?: string;
    output?: JsonValue;
} & Record<string, JsonValue | undefined>;
type ScoredResult = {
    score: number | null;
    metadata?: ScoreMetadata;
};
interface BaseScorerOptions {
    input: string;
    output: string;
    toolCalls?: ToolCallLike[];
}

export type { BaseScorerOptions, ScoreMetadata, ScoredResult, ToolCallLike };
